using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — resolves any type.
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns JsonTypeInfo<T> directly (no cast needed).
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 37), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probe without throwing.
//    With the default resolver every type resolves, so Person succeeds:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {info!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// Now use a source-gen context that only knows about Person.
// Asking for 'Order' (unknown type) should return false, not throw.
var limited = new JsonSerializerOptions { TypeInfoResolver = LimitedContext.Default };

if (limited.TryGetTypeInfo<Order>(out JsonTypeInfo<Order>? orderInfo))
    Console.WriteLine($"TryGetTypeInfo<Order> succeeded → {orderInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Order> returned false (type not in context)");

// --- Types ---------------------------------------------------------------
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

[JsonSerializable(typeof(Person))]
public partial class LimitedContext : JsonSerializerContext;

